  `school_id` varchar(36) NOT NULL,
  `garrison_id` varchar(36) NOT NULL,
  `category_id` varchar(36) DEFAULT NULL,
  `class_id` varchar(36) DEFAULT NULL,
  `academic_year_id` varchar(36) DEFAULT NULL,
  `first_name` varchar(50) NOT NULL,
  `middle_name` varchar(50) DEFAULT NULL,
  `last_name` varchar(50) NOT NULL,
  `dob` date NOT NULL,
  `gender` enum('Male','Female') NOT NULL,
  `jersey_size` varchar(16) DEFAULT NULL,
  `registration_date` date DEFAULT NULL,
  `admission_status` enum('registered','admitted','in_school') DEFAULT NULL,
  `status` enum('active','inactive','graduated') DEFAULT 'active',
  `scores` int DEFAULT '0',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `garrison_id` (`garrison_id`),
  KEY `idx_student_school` (`school_id`),
  KEY `idx_student_class` (`class_id`),
  CONSTRAINT `students_ibfk_1` FOREIGN KEY (`school_id`) REFERENCES `schools` (`id`) ON DELETE CASCADE,
  CONSTRAINT `students_ibfk_2` FOREIGN KEY (`garrison_id`) REFERENCES `garrisons` (`id`) ON DELETE CASCADE
